ạm Ngũ Lão cũ, Quận 1, TP.HCM cũ","google_maps_url":"https://www.google.com/maps/search/?api=1&query_place_id=ChIJCeK0pSIvdTERHitdpk7ETdo&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Kh%C3%A1nh%20Trang%2079%20B%C3%B9i%20Th%E1%BB%8B%20Xu%C3%A2n%20H%E1%BB%93%20Ch%C3%AD%20Minh"}]'::jsonb) AS s(
   ward text,name text,street text,oldward text,cat text,phone text,place text,
   key text,source text,evidence text,address_line text,address_legacy text,google_maps_url text
 )
), vetted AS (
 SELECT s.* FROM src s
 WHERE s.ward IN ('Sài Gòn','Tân Định','Bến Thành')
   AND s.cat IN ('nha_sach','van_phong_pham')
   AND s.source LIKE 'https://%' AND s.address_line ILIKE '%phường '||s.ward||'%'
   AND length(trim(s.name)) BETWEEN 2 AND 240
   AND length(trim(s.address_line)) BETWEEN 3 AND 500
   AND (s.phone IS NULL OR s.phone ~ '^[0-9]{8,11}$')
   AND NOT EXISTS (
     SELECT 1 FROM public.customers c WHERE
      lower(trim(c.name))=lower(trim(s.name)) AND
        (c.province='TP Hồ Chí Minh' OR lower(trim(c.address_line))=lower(trim(s.address_line)))
      OR lower(trim(c.address_line))=lower(trim(s.address_line))
      OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone)
   )
   AND NOT EXISTS (
     SELECT 1 FROM public.field_prospects p WHERE
      p.research_source_key=s.key
      OR (s.place IS NOT NULL AND p.google_place_id=s.place)
      OR lower(trim(p.address_line))=lower(trim(s.address_line))
      OR (p.province='TP Hồ Chí Minh' AND p.district='Quận 1'
          AND lower(trim(p.name))=lower(trim(s.name)))
      OR (s.phone IS NOT NULL AND regexp_replace(coalesce(p.phone,''),'[^0-9]','','g')=s.phone)
   )
), inserted AS (
 INSERT INTO public.field_prospects(
    id,area_visit_id,owner_sub,name,address_line,province,district,ward_new,
    address_legacy,category,phone,tax_code,note,status,source_kind,
    research_source_key,research_source_url,research_batch,google_maps_url,google_place_id
 )
 SELECT gen_random_uuid(),NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
   s.name,s.address_line,'TP Hồ Chí Minh','Quận 1',s.ward,
   s.address_legacy,s.cat,s.phone,NULL,
   'Rà nguồn 22/11/2026; CHƯA GHÉ, chưa có GPS hoặc xác nhận hoạt động tại cửa hàng. '||
   s.evidence||' Nguồn: '||s.source,
   'new','manual',s.key,s.source,
   '2026-11-22-hcm-old-three-wards-street-fill-166',s.google_maps_url,s.place
 FROM vetted s
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING ward_new,name,category,phone,google_place_id
)
SELECT * FROM inserted ORDER BY ward_new,name;